# -*- coding: utf-8 -*-
"""生成 `pandas_golden_test.go`：用**原版模块本身**算出量价特征的黄金值。

为什么这样做：量价特征层几乎全是 `rolling(window, min_periods) / shift / where /
fillna` 的向量化写法，Go 侧的近似实现很容易在"窗口不足时取什么值""NaN 参不参与
聚合"这些细节上悄悄偏离 —— 而这种偏离最终会改变组合买什么。

所以这里**直接 import 原项目的 `volume_price_features`**（它不读远程数据、
不写库，纯函数），在固定输入上跑出全部派生列，再生成一份 Go 测试逐列比对。

用法（需能 import 原项目的 pandas 环境）：

    python internal/volprice/testdata/gen_pandas_golden.py \
        --original "D:\\workspace\\python\\stock\\tushare-stock-tonyz\\pythonProject\\pythonProject" \
        --out internal/volprice/pandas_golden_test.go
"""

from __future__ import annotations

import argparse
import math
import os
import sys


def build_bars(pd):
    """确定性输入：70 根 K 线，含退化的平盘/十字星，用来压 min_periods 边界。

    70 根刚好越过 rolling(60, min_periods=45) 的第 45 个位置与 shift(59)。
    """
    rows = []
    for i in range(70):
        base = 10.0 + i * 0.1 + (i % 7) * 0.3
        open_p = base + ((i % 5) - 2) * 0.05
        close = base + ((i % 3) - 1) * 0.08
        high = max(open_p, close) + 0.2 + (i % 4) * 0.03
        low = min(open_p, close) - 0.15 - (i % 3) * 0.02
        volume = 1_000_000.0 * (1.0 + (i % 11) * 0.07)
        # 退化：第 30 根一字板（high == low），第 45 根十字星（open == close）
        if i == 30:
            high = low = close = open_p
        if i == 45:
            close = open_p
        # 造两段连续缩量，触发 volume_decay 的两级判定
        if 50 <= i <= 52:
            volume = 1_000_000.0 * (1.0 - (i - 49) * 0.1)
        if 60 <= i <= 62:
            volume = 900_000.0 * (1.0 - (i - 59) * 0.15)
        rows.append(
            {
                "trade_date": f"2026{(i // 28) + 1:02d}{(i % 28) + 1:02d}",
                "open": open_p,
                "high": high,
                "low": low,
                "close": close,
                "volume": volume,
            }
        )
    return pd.DataFrame(rows)


def go_str(value) -> str:
    """Go 字符串字面量（json 的转义与 Go 兼容；中文原样输出）。"""
    import json

    return json.dumps(str(value), ensure_ascii=False)


def go_float(value) -> str:
    if value is None:
        return "nan()"
    f = float(value)
    if math.isnan(f):
        return "nan()"
    if math.isinf(f):
        return "math.Inf(1)" if f > 0 else "math.Inf(-1)"
    if f == int(f) and abs(f) < 1e15:
        return f"{f:.1f}"
    return repr(f)


NUMERIC_COLUMNS = [
    "vp_prev_open", "vp_prev_high", "vp_prev_low", "vp_prev_close",
    "vp_close_ma5", "vp_close_ma10", "vp_close_ma20", "vp_close_ma60",
    "vp_close_max5", "vp_close_median60",
    "vp_high_roll20", "vp_low_roll10", "vp_low_roll20",
    "vp_prev20_high", "vp_prev20_low", "vp_prev20_volume_mean",
    "vp_prev30_high", "vp_prev30_low", "vp_prev40_high", "vp_prev40_low",
    "vp_prev60_high", "vp_prev60_low",
    "vp_prev2_volume_mean", "vp_prev3_volume_mean", "vp_prev5_volume_mean",
    "vp_prev8_volume_mean", "vp_prev8_low_min", "vp_prev8_high_max",
    "vp_prev8_close_min", "vp_prev8_down_close_count", "vp_prev10_high_max",
    "vp_prev5_close", "vp_prev10_close", "vp_prev20_close", "vp_prev60_close",
    "vp_close_pos", "vp_lower_shadow_ratio", "vp_upper_shadow_ratio",
    "vp_volume_decay_score", "vp_platform_range_pct", "vp_volume_ratio_20",
    "vp_pullback_ratio", "vp_trend_score", "vp_behavior_quality_score",
]
BOOL_COLUMNS = [
    "vp_higher_high_flag", "vp_higher_low_flag", "vp_support_hold_flag",
    "vp_breakout_flag", "vp_panic_volume_flag", "vp_reversal_flag",
    "vp_three_day_drift", "vp_death_volume_risk",
]
TEXT_COLUMNS = [
    "vp_volume_behavior", "vp_volume_behavior_label",
    "vp_acceptance_quality", "vp_acceptance_quality_label",
    "vp_upper_shadow_behavior", "vp_upper_shadow_behavior_label",
]


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--original", required=True, help="原项目 pythonProject 目录")
    parser.add_argument("--out", required=True, help="要生成的 Go 测试文件")
    args = parser.parse_args()

    if args.original not in sys.path:
        sys.path.insert(0, args.original)

    import pandas as pd  # noqa: E402
    import volume_price_features as vpf  # noqa: E402

    bars = build_bars(pd)
    frame = vpf._attach_vector_bars_columns(bars.copy())

    lines = []
    lines.append("// Code generated by testdata/gen_pandas_golden.py; DO NOT EDIT.")
    lines.append("//")
    lines.append("// 黄金值由**原版 volume_price_features._attach_vector_bars_columns**")
    lines.append("// 在同一份输入上跑出，用来验证 Go 侧 pandas 原语与派生列 1:1。")
    lines.append("package volprice")
    lines.append("")
    # import 的位置留出来，最后按"是否真的用到 math"决定插不插
    import_index = len(lines)
    lines.append("type goldenBar struct {")
    lines.append("\tDate   string")
    lines.append("\tOpen   float64")
    lines.append("\tHigh   float64")
    lines.append("\tLow    float64")
    lines.append("\tClose  float64")
    lines.append("\tVolume float64")
    lines.append("}")
    lines.append("")
    lines.append("var goldenBars = []goldenBar{")
    for _, row in bars.iterrows():
        lines.append(
            "\t{%s, %s, %s, %s, %s, %s},"
            % (
                go_str(row["trade_date"]),
                go_float(row["open"]),
                go_float(row["high"]),
                go_float(row["low"]),
                go_float(row["close"]),
                go_float(row["volume"]),
            )
        )
    lines.append("}")
    lines.append("")

    def emit_series_map(name, columns, element_type, formatter):
        lines.append("var %s = map[string][]%s{" % (name, element_type))
        for column in columns:
            values = frame[column].tolist()
            rendered = ", ".join(formatter(v) for v in values)
            lines.append("\t%s: {%s}," % (go_str(column), rendered))
        lines.append("}")
        lines.append("")

    emit_series_map("goldenNumeric", NUMERIC_COLUMNS, "float64", go_float)
    emit_series_map("goldenBool", BOOL_COLUMNS, "bool", lambda v: "true" if bool(v) else "false")
    emit_series_map("goldenText", TEXT_COLUMNS, "string", go_str)

    # 快照（calculate_feature_snapshot_prepared 的最后一根）
    feature = vpf.calculate_feature_snapshot_prepared(frame)
    lines.append("var goldenSnapshot = struct {")
    lines.append("\tTradeDate string")
    lines.append("\tClose float64")
    lines.append("\tTrendScore float64")
    lines.append("\tHigherHigh bool")
    lines.append("\tHigherLow bool")
    lines.append("\tPlatformHigh float64")
    lines.append("\tPlatformLow float64")
    lines.append("\tPlatformRangePct float64")
    lines.append("\tVolumeRatio20 float64")
    lines.append("\tVolumeDecayScore float64")
    lines.append("\tPullbackRatio float64")
    lines.append("\tSupportPrice float64")
    lines.append("\tSupportHold bool")
    lines.append("\tLowerShadowRatio float64")
    lines.append("\tUpperShadowRatio float64")
    lines.append("\tBreakoutFlag bool")
    lines.append("\tPanicVolumeFlag bool")
    lines.append("\tReversalFlag bool")
    lines.append("\tBehaviorQualityScore float64")
    lines.append("\tDeathVolumeRisk bool")
    lines.append("\tVolumeBehavior string")
    lines.append("\tAcceptanceQuality string")
    lines.append("\tUpperShadowBehavior string")
    lines.append("}{")
    lines.append("\tTradeDate: %s," % go_str(feature.trade_date))
    lines.append("\tClose: %s," % go_float(feature.close))
    lines.append("\tTrendScore: %s," % go_float(feature.trend_score))
    lines.append("\tHigherHigh: %s," % str(bool(feature.higher_high)).lower())
    lines.append("\tHigherLow: %s," % str(bool(feature.higher_low)).lower())
    lines.append("\tPlatformHigh: %s," % go_float(feature.platform_high))
    lines.append("\tPlatformLow: %s," % go_float(feature.platform_low))
    lines.append("\tPlatformRangePct: %s," % go_float(feature.platform_range_pct))
    lines.append("\tVolumeRatio20: %s," % go_float(feature.volume_ratio_20))
    lines.append("\tVolumeDecayScore: %s," % go_float(feature.volume_decay_score))
    lines.append("\tPullbackRatio: %s," % go_float(feature.pullback_ratio))
    lines.append("\tSupportPrice: %s," % go_float(feature.support_price))
    lines.append("\tSupportHold: %s," % str(bool(feature.support_hold)).lower())
    lines.append("\tLowerShadowRatio: %s," % go_float(feature.lower_shadow_ratio))
    lines.append("\tUpperShadowRatio: %s," % go_float(feature.upper_shadow_ratio))
    lines.append("\tBreakoutFlag: %s," % str(bool(feature.breakout_flag)).lower())
    lines.append("\tPanicVolumeFlag: %s," % str(bool(feature.panic_volume_flag)).lower())
    lines.append("\tReversalFlag: %s," % str(bool(feature.reversal_flag)).lower())
    lines.append("\tBehaviorQualityScore: %s," % go_float(feature.behavior_quality_score))
    lines.append("\tDeathVolumeRisk: %s," % str(bool(feature.death_volume_risk)).lower())
    lines.append("\tVolumeBehavior: %s," % go_str(feature.volume_behavior))
    lines.append("\tAcceptanceQuality: %s," % go_str(feature.acceptance_quality))
    lines.append("\tUpperShadowBehavior: %s," % go_str(feature.upper_shadow_behavior))
    lines.append("}")
    lines.append("")

    if "math.Inf" in "\n".join(lines):
        lines[import_index:import_index] = ["import \"math\"", ""]

    os.makedirs(os.path.dirname(os.path.abspath(args.out)), exist_ok=True)
    with open(args.out, "w", encoding="utf-8", newline="\n") as handle:
        handle.write("\n".join(lines))

    # 生成物必须是 gofmt 干净的，否则每次重新生成都会引入无意义的格式 diff
    import shutil
    import subprocess

    gofmt = shutil.which("gofmt")
    if gofmt:
        subprocess.run([gofmt, "-w", args.out], check=True)

    print(f"wrote {args.out}: {len(bars)} bars, "
          f"{len(NUMERIC_COLUMNS)} numeric / {len(BOOL_COLUMNS)} bool / {len(TEXT_COLUMNS)} text columns")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
